import unittest
from settings import load_settings

class SettingsTests(unittest.TestCase):
    def test_default(self):
        self.assertEqual(load_settings({})['timeout_ms'], 2500)

acceptance:
from settings import load_settings
from client import request_options
assert load_settings({}) == {'timeout_ms': 2500}
assert request_options({}) == {'timeout_seconds': 2.5}
for raw, expected in [('1', .001), ('1200', 1.2), ('30000', 30.0)]:
    env = {'REPO_TIMEOUT_MS': raw}
    assert load_settings(env)['timeout_ms'] == int(raw)
    assert request_options(env)['timeout_seconds'] == expected
for raw in ['0', '-1', 'bad', '1.5', '']:
    for fn in [load_settings, request_options]:
        try:
            fn({'REPO_TIMEOUT_MS': raw})
        except ValueError:
            pass
        else:
            raise AssertionError('invalid timeout accepted')

