def timeout_seconds(env):
    value = int(env.get('REPO_TIMEOUT', '30'))
    if value <= 0:
        raise ValueError('timeout must be positive')
    return value

acceptance:
from config import timeout_seconds
assert timeout_seconds({}) == 30
assert timeout_seconds({'REPO_TIMEOUT': '12'}) == 12
for raw in ['0', '-1', 'invalid']:
    try:
        timeout_seconds({'REPO_TIMEOUT': raw})
    except ValueError:
        pass
    else:
        raise AssertionError('invalid timeout accepted')
